/// <summary>
/// Modified method for CheckProforma field
/// </summary>
public void modified()
{
    FormDataObject formDataObject = any2Object(this) as FormDataObject;
    FormDataSource formDataSource = formDataObject.datasource();
    CredManTmpStatusCheckSetup tmpTable;

    next modified();

    tmpTable = formDataSource.cursor();

    if (tmpTable.DocumentStatus == CredManDocumentStatusCheck::METCreditCheck)
    {
        tmpTable.CheckPosting = tmpTable.CheckProforma;
    }
}
